func (q *Queries) SetUserTokensRolesChecked(ctx context.Context, arg SetUserTokensRolesCheckedParams) error {
	_, err := q.db.ExecContext(ctx, setUserTokensRolesChecked, arg.RolesCheckedAt, arg.UserID)
	return err
}

